using System;using System.IO;using System.Drawing;using System.Net.Http;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;
namespace ListeningStudio {
 public sealed class UpdateDialog:Form {
  readonly string home;readonly CancellationTokenSource stop=new CancellationTokenSource();Label state=new Label();TextBox notes=new TextBox();Button check=new Button(),install=new Button(),offline=new Button();string envelope="";UpdateRelease release;bool working;public string ReadyStage="";
  public UpdateDialog(string folder){home=folder;Text="软件更新 · 火山TOS";Size=new Size(640,400);MinimumSize=new Size(540,350);Font=new Font("Microsoft YaHei UI",10);StartPosition=FormStartPosition.CenterParent;var layout=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(18),ColumnCount=1,RowCount=4};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,32));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,48));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,48));Controls.Add(layout);layout.Controls.Add(new Label{Text="当前版本 "+UpdateCore.CurrentVersion+" · 更新保留密钥和所有材料",AutoSize=true},0,0);state.Dock=DockStyle.Fill;state.Text="点击检查更新；无网络时可选择家里下载好的离线更新包。";layout.Controls.Add(state,0,1);notes.Multiline=true;notes.ReadOnly=true;notes.Dock=DockStyle.Fill;notes.ScrollBars=ScrollBars.Vertical;layout.Controls.Add(notes,0,2);var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill};layout.Controls.Add(buttons,0,3);check.Text="检查更新";install.Text="下载并重启更新";offline.Text="从本地更新";foreach(var b in new[]{check,install,offline}){b.AutoSize=true;b.Height=35;buttons.Controls.Add(b);}install.Enabled=false;check.Click+=async(s,e)=>await Check();install.Click+=async(s,e)=>await Download();offline.Click+=(s,e)=>Import();FormClosing+=(s,e)=>{stop.Cancel();};}
  void Busy(bool value){working=value;check.Enabled=offline.Enabled=!value;install.Enabled=!value&&release!=null&&UpdateCore.IsNewer(release.version);}
  async Task Check(){Busy(true);try{using(var http=UpdateCore.Client())using(var timeout=CancellationTokenSource.CreateLinkedTokenSource(stop.Token)){timeout.CancelAfter(15000);envelope=await UpdateCore.Fetch(http,timeout.Token);}release=UpdateCore.VerifyEnvelope(envelope);notes.Text=release.notes;state.Text=UpdateCore.IsNewer(release.version)?"发现版本 "+release.version+"，更新包 "+(release.size/1024.0).ToString("F0")+" KiB。":"已是最新版本 "+release.version+"。";}catch(OperationCanceledException){if(!IsDisposed)state.Text="检查超时或已取消。离线播放不受影响。";release=null;}catch(Exception ex){if(!IsDisposed)state.Text=ex.Message;release=null;}finally{if(!IsDisposed)Busy(false);}}
  async Task Download(){if(release==null||!UpdateCore.IsNewer(release.version))return;Busy(true);try{string stage=UpdateCore.NewStage(home),file=Path.Combine(stage,"bundle.zip");byte[] bytes;using(var http=UpdateCore.Client())using(var timeout=CancellationTokenSource.CreateLinkedTokenSource(stop.Token)){timeout.CancelAfter(120000);var progress=new Progress<long>(n=>{if(!IsDisposed)state.Text="正在下载："+(n/1024)+" / "+(release.size/1024)+" KiB";});bytes=await UpdateCore.Get(http,release.url,release.size,n=>((IProgress<long>)progress).Report(n),timeout.Token);}File.WriteAllBytes(file,bytes);UpdateCore.VerifyBundle(file,release);File.WriteAllText(Path.Combine(stage,"release.json"),envelope,new System.Text.UTF8Encoding(false));UpdateCore.ExtractBundle(file,Path.Combine(stage,"files"));Confirm(stage);}catch(OperationCanceledException){if(!IsDisposed)state.Text="已取消，原程序保持可用。";}catch(Exception ex){if(!IsDisposed)state.Text=ex.Message;}finally{if(!IsDisposed)Busy(false);}}
  void Import(){using(var picker=new OpenFileDialog{Filter="听力软件离线更新包|*.lsupdate",Title="选择离线更新包"}){if(picker.ShowDialog(this)!=DialogResult.OK)return;Busy(true);try{string stage=UpdateCore.ImportOffline(home,picker.FileName);var r=UpdateCore.VerifyEnvelope(File.ReadAllText(Path.Combine(stage,"release.json")));if(!UpdateCore.IsNewer(r.version)){state.Text="该更新包不高于当前版本，无需安装。";return;}notes.Text=r.notes;Confirm(stage);}catch(Exception ex){state.Text=ex.Message;}finally{Busy(false);}}}
  void Confirm(string stage){if(stop.IsCancellationRequested)return;if(MessageBox.Show(this,"更新已校验完成。现在关闭并重新打开软件？\r\n密钥、录音、字幕和分组都会保留。","准备更新",MessageBoxButtons.OKCancel)==DialogResult.OK){ReadyStage=stage;DialogResult=DialogResult.OK;Close();}else state.Text="已取消安装，原程序保持可用。";}
 }
}
